globalThis.reledger=function(id,groups){
 const c=cards.find(x=>x.id===id),old=knowledge.filter(k=>k.card_id===id),orig=groups.map((g,i)=>old.filter(k=>k.answer_anchor==="A"+(i+1)).sort((a,b)=>a.knowledge_id.localeCompare(b.knowledge_id))[0]);
 knowledge=knowledge.filter(k=>k.card_id!==id);c.knowledge_ids=[];
 groups.forEach((g,i)=>{
  const o=orig[i];if(!o)throw new Error("missing original anchor "+id+" A"+(i+1));
  const us=g.units||o.source_units;const ex=us.map(uid=>load("actually_read").find(u=>u.unit_id===uid)).filter(Boolean).map(u=>({unit_id:u.unit_id,text:u.text}));
  g.claims.forEach((q,j)=>{
   const kid=j===0?o.knowledge_id:"KP-CN04-"+String(++ctr.k4).padStart(4,"0");
   c.knowledge_ids.push(kid);knowledge.push({knowledge_id:kid,knowledge:q[0],source_units:us,card_id:id,answer_anchor:"A"+(i+1),rubric_anchor:"R"+(i+1),explicit_recall:true,status:"covered",verified:true,source_excerpt:ex,question_requirement:c.front,rubric_requirement:q[1],verification_note:q[2]||("本次重新人工核对实际源段和完整答案"+(i+1)+"："+q[0]+"；题干明确要求对应机制/条件，评分具体检查‘"+q[1]+"’，已纠正旧multi账本锚错配。")});
  });
 });
 const audit=load("ledger_audit");audit.done.push(id);audit.pending=audit.pending.filter(x=>x!==id);store("ledger_audit",audit);
}

