   knowledge.push({knowledge_id:kid,knowledge:q[0],source_units:p[3],card_id:id,answer_anchor:a,rubric_anchor:r,explicit_recall:true,status:"covered",verified:true,source_excerpt:p[3].map(uid=>load("actually_read").find(u=>u.unit_id===uid)).filter(Boolean).map(u=>({unit_id:u.unit_id,text:u.text})),question_requirement:c.front,rubric_requirement:q[1],verification_note:p[4]||("人工补充核查："+q[0]+"在本源单元直接明确；题干要求完整解释该对象，新增"+a+"给出关系及限定，"+r+"检查‘"+q[1]+"’，已核对该科学内容。")});
  });
